 async function readInspectionProofs(files){
  files=[...files];
  if(files.some(f=>!f.size||f.size>10*1024*1024||!['image/png','image/jpeg','image/webp','application/pdf'].includes(f.type)))throw new Error('请选择 PNG、JPG、WEBP 图片或 PDF，每份不超过 10 MB。');
  return Promise.all(files.map(file=>new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=async()=>{try{if(file.type.startsWith('image/')){const image=new Image();image.src=reader.result;await image.decode();if(!image.naturalWidth)throw new Error();}resolve({name:file.name,type:file.type,size:file.size,data:reader.result});}catch{reject(new Error('图片无法读取，请重新选择有效图片。'));}};reader.onerror=()=>reject(new Error('验收凭证读取失败，请重新选择。'));reader.readAsDataURL(file);})));
 }
